import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test("Vendor names are unique within a tenant, ignoring case", { tag: "@VEN-03" }, async ({ apiAs, factory }) => {
  // Arrange: an existing vendor in the member's tenant. The base name is unique per run,
  // because tests share one database; the duplicate differs from it only by letter case.
  const existingName = uniqueName("Acme Freight");
  const existing = await factory.vendor({ as: "member", name: existingName });
  const duplicateName = existingName.toLowerCase();
  const member = await apiAs("member");

  // Act: create a vendor whose name matches the existing one ignoring case.
  const response = await member.post("/api/vendors", {
    data: { name: duplicateName, category: "logistics", contact_email: "ops@acmefreight.example" },
  });

  // Assert: the duplicate is refused with the documented error code.
  const body = await expectStatus(response, 409);
  expect(body.error.code).toBe("vendor_name_taken");

  // Assert the stored outcome: the tenant still has only the original vendor with that name.
  const list = await expectStatus<{ items: { id: string; name: string }[] }>(
    await member.get("/api/vendors", { params: { q: existingName, limit: 100 } }),
    200,
  );
  const matches = list.items.filter((v) => v.name.toLowerCase() === duplicateName);
  expect(matches.map((v) => v.id)).toEqual([existing.id]);
});
